import { HttpMethod } from '@dapr/dapr';
import {
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { ResourceWithMesInfoResponseDto } from './dto/resource-with-mes-info.response.dto';
import { ResourceDto } from './dto/resource.dto';
import { StorageLocationResponseDTO } from './dto/storage-location.response.dto';
import { UpdateEwmWipDTO } from './dto/update-ewm-dto';
import { UpdateResourceParameterDto } from './dto/update-resource-parameter.dto';
import { UpdateWorkcenter } from './dto/update-workcenter.dto';
import { WorkcenterPlantDto } from './dto/workcenter-plant.dto';
import { WorkcenterResponse } from './dto/workcenter-response.dto';
import { PlantConfigOrder } from './interfaces/plant-config-order.model';
import { PlantConfigShipment } from './interfaces/plant-config-shipment.model';
import { PlanHierarchy } from './interfaces/plant-hierarchy.model';
import { PlantWithConfig } from './interfaces/plant-with-config.model';
import { Plant } from './interfaces/plant.model';
import { ResourceManagementService } from './resource-management/resource-management.service';
import { MaterialRequestDto } from '@/admin/dto/material-request.dto';
import { MaterialWithDtlResponseDto } from '@/admin/dto/material-with-dtl-response.dto';
import { WorkcentersDTO } from '@/admin/dto/workcenters.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class AdminService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(AdminService.name);

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly resourceManagementService: ResourceManagementService,
  ) {
    this.daprClient = new DaprClient();
  }

  public async fetchPlants(): Promise<Array<Plant>> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/Plants`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
    );
    if (response) {
      return response as Array<Plant>;
    }
    throw new Error('Invalid response from fetchPlants');
  }

  // Fetch Plant by ID
  public async fetchPlantById(id: number): Promise<Plant> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/getPlantById/${id}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
    );
    if (response) {
      return response as Plant;
    }
    throw new Error('Invalid response from fetchPlantById');
  }

  public async fetchPlantConfigOrder(
    plantId: number,
  ): Promise<PlantConfigOrder | null> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order/${plantId}`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );

      // Check if the response is valid
      if (response) {
        return response as PlantConfigOrder;
      }
      return null; // Return null if no config is found
    } catch {
      // Log the error but return null to avoid throwing
      return null; // Return null instead of throwing the error
    }
  }

  public async fetchPlantWithConfig(id: number): Promise<PlantWithConfig> {
    // Fetch plant configuration, but allow null as a valid result
    const configOrder = await this.fetchPlantConfigOrder(id);
    // Fetch plant details (will throw if not found)
    const plant = await this.fetchPlantById(id);
    // Merge both into one object and return
    const plantWithConfig: PlantWithConfig = {
      aggrTimeLvlBoard: configOrder?.aggrTimeLvlBoard ?? 60,
      alertCreation: configOrder?.alertCreation ?? 'MANUAL',
      ewmFlow: plant.ewmFlow,
      voiceToActEnabled: plant.voiceToActEnabled ?? false,
      languageCode: plant.languageCode ?? 'EN',
      mleanLink: plant.mleanLink,
      offsetTo: configOrder?.offsetTo ?? 220,
      plantDesc: plant.plantDesc,
      plantId: plant.plantId,
      sid: plant.sid,
      timezone: plant.timezone,
      toleranceValueWk: configOrder?.toleranceValueWk ?? 60,
    };

    return plantWithConfig;
  }

  // Create a new Plant
  public async addPlant(plant: Plant): Promise<Plant> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/addPlant`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      plant,
    );
    if (response) {
      return response as Plant;
    }
    throw new Error('Invalid response from addPlant');
  }

  // Create a new PlantConfig
  public async createPlantConfigShipment(
    dto: PlantConfigShipment,
  ): Promise<PlantConfigShipment> {
    const serviceAppId = this.daprConfigService.shipmentApiAppId;
    const serviceMethod = `plantconfig`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      dto,
    );
    if (response) {
      return response as PlantConfigShipment;
    }
    throw new Error('Invalid response from createPlantConfig');
  }

  public async createPlantConfigOrder(
    dto: PlantConfigOrder,
  ): Promise<PlantConfigOrder> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      dto,
    );
    if (response) {
      return response as PlantConfigOrder;
    }
    throw new Error('Invalid response from createPlantConfig');
  }

  // Combined function to create Plant and PlantConfig
  public async addPlantWithConfig(
    plantWithConfig: PlantWithConfig,
  ): Promise<PlantWithConfig> {
    // Step 1: Create the Plant
    const plant = await this.addPlant({
      ewmFlow: plantWithConfig.ewmFlow,
      languageCode: plantWithConfig.languageCode ?? '',
      mleanLink: plantWithConfig.mleanLink ?? '',
      plantDesc: plantWithConfig.plantDesc ?? '',
      plantId: plantWithConfig.plantId,
      sid: plantWithConfig.sid ?? '',
      timezone: plantWithConfig.timezone ?? '',
      voiceToActEnabled: plantWithConfig.voiceToActEnabled,
    });

    const configOrder = await this.createPlantConfigOrder({
      aggrTimeLvlBoard: plantWithConfig.aggrTimeLvlBoard,
      alertCreation: plantWithConfig.alertCreation,
      offsetTo: plantWithConfig.offsetTo,
      plant: plant.plantId,
      toleranceValueWk: plantWithConfig.toleranceValueWk,
    });
    return {
      ...plant,
      aggrTimeLvlBoard: configOrder.aggrTimeLvlBoard,
      alertCreation: configOrder.alertCreation,
      ewmFlow: plant.ewmFlow,
      voiceToActEnabled: plant.voiceToActEnabled ?? false,
      offsetTo: configOrder.offsetTo,
      toleranceValueWk: configOrder.toleranceValueWk,
    };
  }

  // Update an existing Plant
  public async updatePlant(id: number, plant: Plant): Promise<Plant> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/updatePlant/${id}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      plant,
    );
    if (response) {
      return response as Plant;
    }
    throw new Error('Invalid response from updatePlant');
  }

  public async updatePlantConfigOrder(
    plantId: number,
    aggrTimeLvlBoard: number,
    offsetTo: number,
    toleranceValueWk: number,
    alertCreation: string,
  ): Promise<PlantConfigOrder> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order/${plantId}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.PUT,
      {
        aggrTimeLvlBoard,
        alertCreation,
        offsetTo,
        toleranceValueWk,
      },
    );
    if (response) {
      return response as PlantConfigOrder;
    }

    throw new Error('Invalid response from updatePlantConfig');
  }

  // Combined function to update Plant and PlantConfig
  public async updatePlantWithConfig(
    id: number,
    plantWithConfig: PlantWithConfig,
  ): Promise<PlantWithConfig> {
    // Step 1: Update the Plant
    const updatedPlant = await this.updatePlant(id, {
      ewmFlow: plantWithConfig.ewmFlow,
      languageCode: plantWithConfig.languageCode ?? '',
      mleanLink: plantWithConfig.mleanLink ?? '',
      plantDesc: plantWithConfig.plantDesc ?? '',
      plantId: plantWithConfig.plantId,
      sid: plantWithConfig.sid ?? '',
      timezone: plantWithConfig.timezone ?? '',
      voiceToActEnabled: plantWithConfig.voiceToActEnabled,
    });

    const configOrder = await this.updatePlantConfigOrder(
      id,
      plantWithConfig.aggrTimeLvlBoard,
      plantWithConfig.offsetTo,
      plantWithConfig.toleranceValueWk,
      plantWithConfig.alertCreation,
    );
    return {
      ...updatedPlant,
      aggrTimeLvlBoard: configOrder.aggrTimeLvlBoard,
      alertCreation: configOrder.alertCreation,
      offsetTo: configOrder.offsetTo,
      toleranceValueWk: configOrder.toleranceValueWk,
    };
  }

  // Delete an existing Plant
  public async deletePlant(id: number): Promise<void> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/deletePlant/${id}`;
    await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      {},
    );
  }

  // Delete an existing PlantConfig
  public async deletePlantConfigShipment(plantId: number): Promise<void> {
    const serviceAppId = this.daprConfigService.shipmentApiAppId;
    const serviceMethod = `plantconfig/${plantId}`;

    try {
      await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.DELETE,
      );
    } catch {
      console.error(
        `No plant config found for Plant ID: ${plantId}. Skipping deletion.`,
      );
    }
  }

  public async deletePlantConfigOrder(plantId: number): Promise<void> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order/${plantId}`;

    try {
      await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.DELETE,
      );
    } catch {
      console.error(
        `No plant config found for Plant ID: ${plantId}. Skipping deletion.`,
      );
    }
  }

  // Combined function to delete Plant and PlantConfig
  public async deletePlantWithConfig(id: number): Promise<void> {
    try {
      // Execute both delete operations concurrently
      await Promise.all([
        this.deletePlant(id), // Delete the Plant
        this.deletePlantConfigShipment(id), // Delete the PlantConfig Shipment
        this.deletePlantConfigOrder(id), // Delete the PlantConfig Order
      ]);
    } catch (error) {
