  public async getMaterialsByPlantAndSapServer(
    plant: string,
  ): Promise<Array<MaterialWithDtlResponseDto>> {
    try {
      // Step 1: Get the SAP server for the plant
      const { sapServer } = await this.getSapServerByPlant(plant);

      if (!sapServer) {
        throw new Error(`SAP server not found for plant ${plant}`);
      }

      // Step 2: Use the SAP server to get all materials
      const materials = await this.getAllMaterialWithDeteals(plant, sapServer);
      return materials;
    } catch (error) {
      this.logger.error(
        `Failed to get materials for plant ${plant}: ${error.message}`,
        error.stack,
      );
      throw error; // Re-throw to allow upstream handling
    }
  }

  public async updateMaterial(
    updateDto: MaterialRequestDto,
    plant?: string,
  ): Promise<Response> {
    let dtoToSend = { ...updateDto };

    // If sapServer is missing and we have a plant, fetch it
    if (!dtoToSend.sapServer) {
      if (!plant) {
        throw new Error('sapServer not provided and plant not specified');
      }

      const sapServerResponse = await this.getSapServerByPlant(plant);
      dtoToSend = {
        ...dtoToSend,
        sapServer: String(sapServerResponse.sapServer),
      };
    }

    const token = `Bearer ${process.env.TOKEN}`;
    const options = {
      headers: { authorization: token },
    };

    const serviceAppId = this.daprConfigService.masterApiAppId;
    const serviceMethod = '/material/updateMaterial';

    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.PUT,
      dtoToSend,
      options,
    );

    if (response) {
      return response as Response;
    }

    throw new Error('Invalid response from update material');
  }

