  public async updateMaterialsBulkByPlantAndSapServer(
    plant: string,
    updateDto: Array<MaterialRequestDto>,
  ): Promise<Response | undefined> {
    try {
      // Step 1: Get SAP server for the plant
      const { sapServer } = await this.getSapServerByPlant(plant);

      if (!sapServer) {
        throw new Error(`SAP server not found for plant ${plant}`);
      }

      // Step 2: Use SAP server to perform bulk update
      const response = await this.updateMaterialsBulk(
        plant,
        sapServer,
        updateDto,
      );

      return response;
    } catch (error) {
      this.logger.error(
        `Failed to update materials for plant ${plant}: ${error.message}`,
        error.stack,
      );

      // Rethrow with InternalServerErrorException but include original message
      throw new InternalServerErrorException(
        `Failed to update materials for plant ${plant}: ${error.message}`,
      );
    }
  }

